# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.parsing import parse_span
from hourglass.models import Shift

def shift(worker, day, text):
    return Shift(worker, day, parse_span(text))

class TimesheetRowsTests(unittest.TestCase):
    def test_busiest_first(self):
        rows = timesheet_rows([
            shift("Ana", "mon", "09:00-10:00"),
            shift("Brisa", "mon", "09:00-13:30"),
            shift("Brisa", "tue", "09:00-12:00"),
        ])
        self.assertEqual(rows, [
            "Brisa: 2 shifts, 7.5 hours",
            "Ana: 1 shift, 1.0 hours"
        ])

    def test_hours_to_one_decimal(self):
        rows = timesheet_rows(
            [shift("Ana", "mon", "09:00-09:20")]
        )
        self.assertEqual(
            rows, ["Ana: 1 shift, 0.3 hours"]
        )

    def test_ties_sorted_by_name(self):
        rows = timesheet_rows([
            shift("Zed", "mon", "09:00-10:00"),
            shift("Ana", "tue", "09:00-10:00")
        ])
        self.assertTrue(rows[0].startswith("Ana"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows(
                [shift("  ", "mon", "09:00-10:00")]
            )

if __name__ == "__main__":
    unittest.main()
